<template>
  <q-expansion-item
    class="issue-cluster-card"
    :class="`issue-cluster-card--${severity}`"
    :data-test="`touchless-issue-${issue.issue_signature}`"
    expand-separator
  >
    <template #header>
      <q-item-section>
        <q-item-label class="issue-headline">
          {{ blockerLabel }}
        </q-item-label>
        <q-item-label caption data-test="touchless-issue-cause">
          {{ causeLine }}
        </q-item-label>
      </q-item-section>
      <q-item-section side>
        <div class="row items-center no-wrap q-gutter-sm">
          <!-- Affected/recoverable and the expected lift belong in the HEADER,
               not behind a click. The lift is what decides which cause gets
               worked first, so a queue that hides it until the card is
               expanded makes the reader open every card to rank them. -->
          <div class="issue-counts">
            <span data-test="touchless-issue-affected">
              {{
                $t('touchless_affected_docs', {
                  count: issue.affected_doc_count,
                })
              }}
            </span>
            <span class="issue-counts-sub">
              {{
                $t('touchless_recoverable_short', {
                  count: issue.recoverable_doc_count,
                })
              }}
            </span>
          </div>
          <div class="issue-lift" data-test="touchless-issue-lift">
            <span class="issue-lift-value">{{ liftLabel }}</span>
            <span class="issue-lift-caption">
              {{ $t('touchless_col_expected_lift') }}
            </span>
          </div>
          <!-- A generation is a BACKGROUND job, so a collapsed card has to say
               it is working without being opened. The chip carries the elapsed
               seconds — a measured number — never a share of an unknown whole. -->
          <q-chip
            v-if="adviceIsRunning"
            dense
            square
            outline
            color="primary"
            icon="autorenew"
            :label="adviceRunningChipLabel"
            data-test="touchless-issue-advice-running-chip"
          >
            <q-tooltip>{{ advicePhaseLabel }}</q-tooltip>
          </q-chip>
          <!-- Provenance BEFORE status, because it qualifies everything to its
               left: "open" on a rule's finding and "open" on a model's guess
               are not the same claim, and the reader has to know which one
               they are looking at before they read the cause at all. -->
          <q-chip
            v-if="provenanceLabel"
            dense
            square
            outline
            :color="provenanceChipColor"
            :icon="provenanceChipIcon"
            :label="provenanceLabel"
            data-test="touchless-issue-provenance"
          >
            <q-tooltip v-if="provenanceHint">{{ provenanceHint }}</q-tooltip>
          </q-chip>
          <!-- No status, no chip. An empty outlined box beside a real cause
               reads as a status nobody bothered to name; the API simply does
               not send one for most clusters. -->
          <q-chip
            v-if="statusLabel"
            dense
            square
            outline
            :label="statusLabel"
            data-test="touchless-issue-status"
          />
        </div>
      </q-item-section>
    </template>

    <q-card flat>
      <q-card-section class="issue-body">
        <div class="issue-field">
          <span class="issue-field-label">
            {{ $t('touchless_first_blocker') }}
          </span>
          <span data-test="touchless-issue-blocker">{{ blockerLabel }}</span>
        </div>

        <div class="issue-field">
          <!-- "Suspected" when a model proposed it. Calling a machine's guess
               a confirmed cause is the one mistake this feature cannot make. -->
          <span class="issue-field-label" data-test="touchless-issue-cause-label">
            {{ causeFieldLabel }}
          </span>
          <span>{{ causeLine }}</span>
        </div>

        <div class="issue-field">
          <span class="issue-field-label">
            {{ $t('touchless_evidence_summary') }}
          </span>
          <span data-test="touchless-issue-evidence">
            {{ evidenceSummary || '-' }}
          </span>
        </div>

        <!-- What to change, and WHERE. The fixability chip says what kind of
             change it is (and drives the stripe on the card's left edge); the
             steps say which screen to open. -->
        <div class="issue-field issue-field--stacked">
          <span class="issue-field-label">
            {{ $t('touchless_fix_steps') }}
          </span>
          <div class="issue-fix">
            <q-chip
              dense
              square
              color="secondary"
              text-color="white"
              :label="fixabilityLabel"
              data-test="touchless-issue-fixability"
            />
            <TouchlessFixStepList
              :steps="fixSteps"
              data-test-prefix="touchless-issue-fix-step"
            />
            <div
              v-if="showsNoFixSteps"
              class="issue-no-steps"
              data-test="touchless-issue-no-fix-steps"
            >
              {{ $t('touchless_no_fix_steps') }}
            </div>
          </div>
        </div>

        <!-- The advisor block sits BESIDE the deterministic answer above, never
             over it. Everything that already reads correctly — the cause, the
             owner, the settings route — is exactly what somebody reads while
             they wait, so no state here replaces it with a skeleton. -->
        <div
          class="issue-field issue-field--stacked"
          data-test="touchless-issue-advice-actions"
        >
          <span class="issue-field-label">
            {{ $t('touchless_advice_section') }}
          </span>
          <div class="issue-advice">
            <q-btn
              v-if="showsGenerateButton"
              dense
              no-caps
              unelevated
              color="primary"
              icon="auto_awesome"
              :label="$t('touchless_generate_advice')"
              :disable="adviceIsRunning"
              data-test="touchless-issue-generate"
              @click="onGenerateAdvice"
            />

            <!-- Indeterminate on purpose: the only honest quantity here is how
                 long it has been going, and that is printed beside the bar. -->
            <div
              v-if="adviceIsRunning"
              class="issue-advice-progress"
              data-test="touchless-issue-advice-progress"
            >
              <q-linear-progress
                indeterminate
                rounded
                size="4px"
                color="primary"
                class="issue-advice-bar"
                data-test="touchless-issue-advice-bar"
              />
              <div class="issue-advice-line">
                <span data-test="touchless-issue-advice-phase">
                  {{ advicePhaseLabel }}
                </span>
                <span
                  v-if="adviceElapsedLabel"
                  data-test="touchless-issue-advice-elapsed"
                >
                  {{ adviceElapsedLabel }}
                </span>
              </div>
            </div>

            <div
              v-else-if="advicePhase === 'ready'"
              class="issue-advice-note"
              data-test="touchless-issue-advice-ready"
            >
              {{ $t('touchless_advice_ready') }}
            </div>

            <!-- A timeout is NOT a failure: the job may still be finishing, and
                 a later visit will show its result. Hence "look again", not an
                 error, and a button that only resumes reading. -->
            <div
              v-else-if="advicePhase === 'timeout'"
              class="issue-advice-note"
              data-test="touchless-issue-advice-timeout"
            >
              {{ $t('touchless_advice_timeout') }}
              <q-btn
                flat
                dense
                no-caps
                size="sm"
                icon="refresh"
                :label="$t('touchless_advice_check_again')"
                data-test="touchless-issue-advice-recheck"
                @click="onResumeAdvice"
              />
            </div>

            <div
              v-else-if="advicePhase === 'disabled'"
              class="issue-advice-note"
              data-test="touchless-issue-advice-disabled"
            >
              {{ $t('touchless_advice_disabled') }}
            </div>

            <div
              v-else-if="advicePhase === 'forbidden'"
              class="issue-advice-note"
              data-test="touchless-issue-advice-forbidden"
            >
              {{ $t('touchless_advice_forbidden') }}
            </div>

            <div
              v-else-if="advicePhase === 'not_found'"
              class="issue-advice-note"
              data-test="touchless-issue-advice-not-found"
            >
              {{ $t('touchless_advice_not_found') }}
            </div>

            <div
              v-else-if="showsAdviceFailure"
              class="issue-advice-note"
              data-test="touchless-issue-advice-unavailable"
            >
              {{ $t('touchless_advice_unavailable') }}
              <q-btn
                flat
                dense
                no-caps
                size="sm"
                icon="refresh"
                :label="$t('retry')"
                data-test="touchless-issue-advice-retry"
                @click="onGenerateAdvice"
              />
              <!-- The server's own message. Shown verbatim: a validator
                   rejection names the field it rejected, and paraphrasing it
                   would cost the only clue anybody has. -->
              <div
                v-if="adviceFailureDetail"
                class="issue-advice-error text-grey-6"
                data-test="touchless-issue-advice-error"
              >
                {{ adviceFailureDetail }}
              </div>
            </div>
          </div>
        </div>

        <div class="issue-field">
          <span class="issue-field-label">{{ $t('touchless_owner') }}</span>
          <q-chip
            dense
            square
            outline
            :label="ownerLabel"
            data-test="touchless-issue-owner"
          />
        </div>

        <div class="issue-field">
          <span class="issue-field-label">
            {{ $t('touchless_col_recoverable') }}
          </span>
          <span>
            {{
              $t('touchless_recoverable_summary', {
                recoverable: issue.recoverable_doc_count,
                lift: formatPct(issue.potential_pure_lift_pct),
              })
            }}
          </span>
        </div>

        <div class="issue-field">
          <span class="issue-field-label">
            {{ $t('touchless_col_confidence') }}
          </span>
          <q-chip
            dense
            square
            :color="confidenceColor"
            text-color="white"
            :label="confidenceLabel"
          />
        </div>

        <!-- What the advisor could NOT answer, collapsed. Hiding it entirely
             would present a partial answer as a complete one; putting it in
             the open would bury the recommendation under its own caveats. -->
        <q-expansion-item
          v-if="gapCount > 0"
          dense
          class="issue-gaps"
          :label="$t('touchless_advice_gaps', { count: gapCount })"
          data-test="touchless-issue-gaps"
        >
          <div v-if="missingEvidence.length" class="issue-gap-group">
            <div class="issue-field-label">
              {{ $t('touchless_missing_evidence') }}
            </div>
            <ul class="issue-gap-list">
              <li v-for="(item, index) in missingEvidence" :key="`ev-${index}`">
                {{ item }}
              </li>
            </ul>
          </div>
          <div v-if="openQuestions.length" class="issue-gap-group">
            <div class="issue-field-label">
              {{ $t('touchless_open_questions') }}
            </div>
            <ul class="issue-gap-list">
              <li v-for="(item, index) in openQuestions" :key="`oq-${index}`">
                {{ item }}
              </li>
            </ul>
          </div>
        </q-expansion-item>

        <div
          v-if="generatedCaption"
          class="issue-generated"
          data-test="touchless-issue-generated"
        >
          {{ generatedCaption }}
        </div>
        <div v-if="showsLanguageNote" class="issue-generated">
          {{ $t('touchless_advice_language_note') }}
        </div>

        <q-separator class="q-my-sm" />

        <div class="issue-field-label q-mb-xs">
          {{ $t('touchless_sample_documents') }}
        </div>
        <EvidenceDocList :doc-ids="issue.sample_doc_ids || []" />
      </q-card-section>
    </q-card>
  </q-expansion-item>
</template>

<script lang="ts">
import { computed, defineComponent, inject, type PropType } from 'vue';
import { useTolgee } from '@tolgee/vue';
import EvidenceDocList from './EvidenceDocList.vue';
import TouchlessFixStepList from './TouchlessFixStepList.vue';
import type {
  TouchlessAdvice,
  TouchlessFixStep,
  TouchlessIssue,
} from 'src/services/analytics/TouchlessService';
import {
  confidenceBand,
  confidenceColor as confidenceColorFor,
  formatLiftPp,
  formatTouchlessPct,
  isHypothesis,
  provenanceColor,
  provenanceIcon,
  NO_VALUE,
} from 'src/utils/touchless-format';
import {
  adviceElapsedSeconds,
  isAdviceRunActive,
  ADVICE_STATUS_FAILED,
  ADVICE_STATUS_RUNNING,
} from 'src/utils/touchless-advice';
import type {
  TouchlessAdvicePhase,
  TouchlessAdviceRun,
} from 'src/utils/touchless-advice';

/**
 * One issue cluster for a supplier: where it blocks, what the cause is, WHERE
 * that cause came from, the evidence behind it, and what to change to fix it.
 *
 * Two sources, one card
 * ---------------------
 * The same four narrative fields (`confirmed_cause`, `evidence_summary`,
 * `owner`, `status`) can arrive twice: flat on the cluster, where the backend's
 * deterministic tier writes them, and inside `advice`, where the advisor writes
 * them. The advisor's answer is the more specific one and wins; the flat fields
 * are the fallback; and when neither exists the card says so rather than
 * showing empty rows. Every read goes through a computed for exactly that
 * reason — an inline `a || b` in the template drifts between the header and the
 * body, which is how the header once said "confirmed" over an empty body.
 *
 * Still read-only. Confirm/dismiss actions belong to PR-F3, where a server-side
 * status endpoint exists behind them; offering the buttons now would promise an
 * action nothing can carry out. The wording is "Confirmed", never
 * "approve"/"reject" — a Playwright assertion checks the whole page for those
 * two words.
 */
export default defineComponent({
  name: 'IssueClusterCard',

  components: { EvidenceDocList, TouchlessFixStepList },

  props: {
    issue: {
      type: Object as PropType<TouchlessIssue>,
      required: true,
    },
    /**
     * The advisor run for THIS cluster, owned by the dashboard store and handed
     * down. The card stays presentational: it neither starts the job nor holds
     * its state, because a 40-second job whose only record lives in a component
     * is forgotten the moment that component unmounts — and this one unmounts
     * on every navigation away from the supplier page.
     */
    adviceRun: {
      type: Object as PropType<TouchlessAdviceRun | null>,
      default: null,
    },
    /**
     * `Date.now()` from the store's shared one-second tick. Passed in rather
     * than read here so every card's elapsed readout shows the same number.
     */
    adviceClock: {
      type: Number,
      default: 0,
    },
  },

  emits: ['generate-advice', 'resume-advice'],

  /**
   * The language the READER is actually looking at.
   *
   * Tolgee's active language, not vue-i18n's locale: the locale is seeded from
   * `navigator.language` and is never updated by the language picker, so
   * comparing the advisor's language against it compared the wrong two things
   * — a German browser reading an English UI would have been told nothing, and
   * an English browser reading German told the note constantly.
   *
   * Same pattern as `Settings/Components/Sub-Header.vue`. The injection is
   * probed first because `useTolgee` dereferences it immediately and would
   * throw wherever Tolgee is not installed — component tests, most of all,
   * where the note then simply stays silent.
   */
  setup() {
    const tolgee = inject('tolgeeContext', null) ? useTolgee(['language']) : null;
    const uiLanguage = computed(() => tolgee?.value?.getLanguage() || '');
    return { uiLanguage };
  },

  computed: {
    /**
     * The advice the card renders.
     *
     * A finished run wins over the prop: the run has just read the cluster back
     * from the server, while `issue.advice` is whatever the supplier diagnosis
     * carried when the page last loaded — which for a cluster generated a
     * moment ago still says `status: "running"` with no content. Falling back
     * the other way would make a successful generation invisible until the
     * reader reloaded the page by hand.
     */
    advice(): TouchlessAdvice | null {
      const fromRun = this.adviceRun?.advice;
      if (fromRun && typeof fromRun === 'object') return fromRun;
      const advice = this.issue.advice;
      return advice && typeof advice === 'object' ? advice : null;
    },

    advicePhase(): TouchlessAdvicePhase | null {
      return this.adviceRun?.phase ?? null;
    },

    /**
     * Running, from whichever source knows.
     *
     * A local run wins outright — including a FINISHED one, because the prop's
     * `advice.status` is still the stale "running" the diagnosis was loaded
     * with and would otherwise pin the card in progress forever.
     *
     * With no local run, the SERVER decides. That is what makes an in-flight
     * generation survive a full page reload: the row the worker claimed reads
     * back as `status: "running"`, and the card picks the job up again instead
     * of pretending nothing is happening.
     */
    adviceIsRunning(): boolean {
      const phase = this.advicePhase;
      if (phase) return isAdviceRunActive(phase);
      // A terminally-failed row is NOT running, even though it was claimed as
      // `running` a moment before it failed (DOCB-14285). Checking only for
      // the `running` string is what pinned this card in a spinner forever
      // when the advisor rejected its own output: the worker wrote
      // `last_error` and gave up, but the status column still said running,
      // so every later reader — a reload, another user — saw a job in flight
      // that nothing was working on.
      if (this.serverAdviceFailed) return false;
      return this.issue.advice?.status === ADVICE_STATUS_RUNNING;
    },

    /**
     * The SERVER says this generation ended badly, with no local run to say
     * otherwise.
     *
     * `status === 'failed'` is the terminal marker the backend writes
     * alongside `last_error`. `last_error` alone counts too: it is the older
     * signal, so a row written before the terminal status shipped still
     * renders its error and its retry instead of spinning.
     */
    serverAdviceFailed(): boolean {
      if (this.advicePhase) return false;
      const advice = this.issue.advice;
      if (!advice) return false;
      if (advice.status === ADVICE_STATUS_FAILED) return true;
      return this.firstText(advice.last_error) !== null;
    },

    /**
     * Whether an advisor answer already stands for this cluster.
     *
     * Judged as "the advisor produced something and did not fail". True
     * freshness is a server-side hash of the evidence, prompt and model that no
     * client can reproduce — and it does not need to: a click on a cluster
     * whose cache is still fresh comes back `ready` without spending anything,
     * so the only cost of being wrong here is a hidden button, never a wasted
     * generation.
     */
    adviceIsCurrent(): boolean {
      const advice = this.advice;
      if (!advice) return false;
      if (this.firstText(advice.last_error)) return false;
      return this.firstText(advice.generated_at) !== null;
    },

    /**
     * A cluster with no reason code has nothing for the advisor to explain —
     * the evidence pack is built from the reason, and asking anyway spends a
     * model call to be told so.
     */
    hasReasonCode(): boolean {
      return this.firstText(this.issue.reason_code) !== null;
    },

    /** Every ending that puts its own wording where the button would be. */
    showsAdviceOutcome(): boolean {
      const phase = this.advicePhase;
      // A server-side failure is an ending too — without this the card would
      // show the failure note AND a Generate button beside it, two controls
      // for one action.
      if (!phase) return this.serverAdviceFailed;
      return !isAdviceRunActive(phase);
    },

    /**
     * Both endings that mean "no explanation this time". They read the same to
     * a reader and both offer another attempt; only the log distinguishes a
     * released claim from a thrown request.
     */
    showsAdviceFailure(): boolean {
      // The third case has no local run at all: the generation failed before
      // this reader arrived, and the row says so.
      if (this.serverAdviceFailed) return true;
      return this.advicePhase === 'unavailable' || this.advicePhase === 'failed';
    },

    /**
     * The server's own wording for a failure, shown under the note so the
     * reader sees WHAT went wrong rather than only THAT something did.
     */
    adviceFailureDetail(): string {
      const fromRun = this.firstText(this.adviceRun?.message);
      if (fromRun) return fromRun;
      return this.firstText(this.issue.advice?.last_error) || '';
    },

    showsGenerateButton(): boolean {
      if (!this.hasReasonCode) return false;
      if (this.adviceIsRunning) return false;
      if (this.adviceIsCurrent) return false;
      // An ending already speaks for itself, and the ones that can be retried
      // carry their own button.
      return !this.showsAdviceOutcome;
    },

    /**
     * Seconds since the click, or null when nothing local knows the start —
     * after a hard reload the server still says "running" but the start time
     * is gone, and a made-up one would be worse than no number.
     */
    adviceElapsed(): number | null {
      if (!this.adviceIsRunning) return null;
      return adviceElapsedSeconds(this.adviceRun?.startedAt, this.adviceClock);
    },

    adviceElapsedLabel(): string {
      const seconds = this.adviceElapsed;
      if (seconds === null) return '';
      return this.$t('touchless_advice_elapsed', { seconds }) as string;
    },

    /** The phase named by the event that produced it, never by a timer. */
    advicePhaseLabel(): string {
      switch (this.advicePhase) {
        case 'dispatching':
          return this.$t('touchless_advice_phase_dispatching') as string;
        case 'reading':
          return this.$t('touchless_advice_phase_reading') as string;
        default:
          return this.$t('touchless_advice_phase_running') as string;
      }
    },

    adviceRunningChipLabel(): string {
      return this.adviceElapsedLabel || (this.$t('touchless_advice_running') as string);
    },

    /**
     * Same shape as the blocking chart's bar label: the stage when there is
     * one, the reason alone when the cluster could not be attributed to a
     * stage (4 of 26 clusters on dev).
     */
    blockerLabel(): string {
      const stage = this.issue.stage
        ? this.translateEnum('touchless_stage_', this.issue.stage)
        : '';
      const reason = this.translateEnum(
        'touchless_reason_',
        this.issue.reason_code,
      );
      if (!stage) return reason;
      return reason ? `${stage} — ${reason}` : stage;
    },

    /**
     * WHICH source the rendered cause came from. Everything that qualifies
     * that cause — the provenance chip, its tooltip, the "Suspected"/"
     * Confirmed" label — is derived from this and nothing else.
     *
     * The bug this replaces: the cause fell back advice→cluster while the
     * provenance fell back independently. A model hypothesis with no
     * `advice.provenance` therefore borrowed the cluster's flat
     * `DETERMINISTIC` and was presented as rule-derived; the inverse labelled
     * a flat deterministic cause as model-authored. Two independent fallbacks
     * over the same pair of sources cannot be kept in agreement, so there is
     * now only one.
     */
    causeSource(): 'advice' | 'cluster' | null {
      if (this.firstText(this.advice?.confirmed_cause)) return 'advice';
      if (this.firstText(this.issue.confirmed_cause)) return 'cluster';
      return null;
    },

    /**
     * The provenance OF THE RENDERED CAUSE.
     *
     * When the advisor wrote the cause, only the advisor may say where it came
     * from: its own `provenance`, or `AGENT_HYPOTHESIS` implied by the
     * `hypothesis` flag. If it says neither, the card shows NO chip — an
     * honest silence, rather than the cluster's answer to a different
     * question.
     *
     * With no advisor-written cause (every cluster today), this is the
     * cluster's own `provenance`, which is what the API already sends.
     */
    provenance(): string {
      if (this.causeSource === 'advice') {
        return (
          this.firstText(this.advice?.provenance) ??
          (this.advice?.hypothesis === true ? 'AGENT_HYPOTHESIS' : '')
        );
      }
      return this.firstText(this.issue.provenance) ?? '';
    },

    /**
     * A model's guess.
     *
     * Inside the advice branch the `hypothesis` flag still wins over a
     * contradictory provenance string, because the two directions of that
     * mistake are not equally expensive: calling a guess "confirmed" is the
     * one this feature cannot afford. It does NOT leak across sources — an
     * advisor flag cannot relabel a cause the advisor did not write.
     */
    isHypothesisCause(): boolean {
      if (this.causeSource === 'advice' && this.advice?.hypothesis === true) {
        return true;
      }
      return isHypothesis(this.provenance);
    },

    provenanceLabel(): string {
      return this.translateEnum('touchless_provenance_', this.provenance);
    },

    provenanceHint(): string {
      if (!this.provenance) return '';
      return this.translateOrEmpty(
        `touchless_provenance_hint_${this.provenance.toLowerCase()}`,
      );
    },

    provenanceChipColor(): string {
      return provenanceColor(this.provenance);
    },

    provenanceChipIcon(): string {
      return provenanceIcon(this.provenance);
    },

    /** Whatever `causeSource` picked — read through it, never beside it. */
    confirmedCause(): string {
      if (this.causeSource === 'advice') {
        return this.firstText(this.advice?.confirmed_cause) ?? '';
      }
      if (this.causeSource === 'cluster') {
        return this.firstText(this.issue.confirmed_cause) ?? '';
      }
      return '';
    },

    causeLine(): string {
      return (
        this.confirmedCause || (this.$t('touchless_cause_unconfirmed') as string)
      );
    },

    causeFieldLabel(): string {
      return this.$t(
        this.isHypothesisCause
          ? 'touchless_suspected_cause'
          : 'touchless_confirmed_cause',
      ) as string;
    },

    evidenceSummary(): string {
      return (
        this.firstText(
          this.advice?.evidence_summary,
          this.issue.evidence_summary,
        ) ?? ''
      );
    },

    statusLabel(): string {
      const status = this.firstText(this.advice?.status, this.issue.status);
      return this.translateEnum('touchless_status_', status);
    },

    fixSteps(): TouchlessFixStep[] {
      const fromAdvice = this.advice?.fix_steps;
      if (Array.isArray(fromAdvice)) return fromAdvice;
      const fromCluster = this.issue.fix_steps;
      return Array.isArray(fromCluster) ? fromCluster : [];
    },

    /**
     * "No concrete steps yet" is a FINDING, and only a completed advisor run
     * can make it. Three states have to be told apart:
     *
     *   fix_steps: []          the advisor looked and found none  → say so
     *   last_error: "timeout"  the advisor failed open            → stay silent
     *   no fix_steps key       nothing has looked yet             → stay silent
     *
     * The previous version said it for all three, because the mere PRESENCE of
     * an advice row was taken as an answer. A fail-open row is the opposite of
     * an answer, and printing a finding over one turns an outage into a claim
     * that this cluster has nothing to do about it.
     */
    showsNoFixSteps(): boolean {
      const advice = this.advice;
      if (!advice) return false;
      if (this.firstText(advice.last_error)) return false;
      return Array.isArray(advice.fix_steps) && this.fixSteps.length === 0;
    },

    ownerLabel(): string {
      const owner = this.firstText(this.advice?.owner, this.issue.owner);
      // Known tokens (customer/consultant/supplier/docbits) translate; legacy
      // free text ("AP Operations") passes through raw, which is still the
      // most useful thing to show.
      const translated = this.translateEnum('touchless_owner_', owner);
      if (translated) return translated;
      return (
        this.firstText(this.advice?.owner_label, this.issue.owner_label) ??
        (this.$t('touchless_owner_unassigned') as string)
      );
    },

    missingEvidence(): string[] {
      return this.textList(this.advice?.missing_evidence);
    },

    openQuestions(): string[] {
      return this.textList(this.advice?.open_questions);
    },

    gapCount(): number {
      return this.missingEvidence.length + this.openQuestions.length;
    },

    /** "Generated by {model}, {date}" — provenance the reader can date. */
    generatedCaption(): string {
      const model = this.firstText(this.advice?.model);
      if (!model) return '';
      return this.$t('touchless_advice_generated', {
        model,
        date: this.formatDate(this.advice?.generated_at),
      }) as string;
    },

    /**
     * The advisor writes in the ORGANISATION's language, which is not
     * necessarily the language this screen is being read in. Said only when
     * the two actually differ — and never when the UI language is unknown, so
     * a mount without Tolgee does not announce a mismatch it cannot see.
     */
    showsLanguageNote(): boolean {
      const language = this.firstText(this.advice?.language);
      if (!language) return false;
      const uiLanguage = this.uiLanguage;
      if (!uiLanguage) return false;
      // Compared on the base tag: de-DE and de are the same language to a
      // reader, and the note is about being unable to read the text at all.
      return (
        uiLanguage.slice(0, 2).toLowerCase() !==
        language.slice(0, 2).toLowerCase()
      );
    },

    /**
     * The lift, formatted for the header. Signed, because a reader scanning
     * the queue is comparing magnitudes and a bare "18.7 %" reads as a share
     * rather than as points gained.
     */
    liftLabel(): string {
      return formatLiftPp(this.issue.potential_pure_lift_pct);
    },

    /**
     * Severity stripe on the card's left edge, derived from how the cause is
     * fixed rather than from its size: a configuration change we control is a
     * different kind of work from a supplier-side or model problem, and the
     * queue is read to decide what to pick up next.
     */
    severity(): 'config' | 'data' | 'external' {
      switch (this.issue.fixability_code) {
        case 'CONFIG_FIX':
          return 'config';
        case 'MASTER_DATA_FIX':
        case 'SUPPLIER_TEMPLATE_FIX':
          return 'data';
        default:
          return 'external';
      }
    },

    fixabilityLabel(): string {
      return this.translateEnum(
        'touchless_fixability_',
        this.issue.fixability_code,
      );
    },

    /**
     * The API sends a 0-1 score, not a label. `String(0.9)` looked up the key
     * `touchless_confidence_0.9`, found nothing and printed the raw "0.9";
     * a null score printed the literal "null".
     */
    confidenceLabel(): string {
      const band = confidenceBand(
        this.advice?.confidence ?? this.issue.confidence,
      );
      if (band === null) return NO_VALUE;
      return this.translateEnum('touchless_confidence_', band);
    },

    confidenceColor(): string {
      return confidenceColorFor(
        this.advice?.confidence ?? this.issue.confidence,
      );
    },
  },

  methods: {
    /**
     * Hands the cluster's CURRENT advice up with the request: the store uses it
     * as the baseline the poll compares against, so "changed" means changed
     * from what this reader was looking at when they clicked.
     */
    onGenerateAdvice(): void {
      this.$emit('generate-advice', {
        signature: this.issue.issue_signature,
        advice: this.advice,
      });
    },

    onResumeAdvice(): void {
      this.$emit('resume-advice', {
        signature: this.issue.issue_signature,
      });
    },

    formatPct(value: unknown): string {
      return formatTouchlessPct(value);
    },

    /**
     * The first candidate that is a non-empty string, or null.
     *
     * `??` alone is not enough: the API sends `''` for an unset owner, and
     * `'' ?? fallback` is `''` — an empty row where the fallback belonged.
     */
    firstText(...candidates: unknown[]): string | null {
      for (const candidate of candidates) {
        if (typeof candidate === 'string' && candidate.trim().length > 0) {
          return candidate;
        }
      }
      return null;
    },

    /** Non-empty strings only; anything else in the array is dropped. */
    textList(value: unknown): string[] {
      if (!Array.isArray(value)) return [];
      return value.filter(
        (item): item is string =>
          typeof item === 'string' && item.trim().length > 0,
      );
    },

    /** i18n label for an enum value, falling back to the raw backend value. */
    translateEnum(prefix: string, value: string | null | undefined): string {
      if (!value) return '';
      const key = `${prefix}${String(value).toLowerCase()}`;
      const translated = this.$t(key) as string;
      return translated === key ? value : translated;
    },

    /**
     * A translation, or '' when the key is missing — for optional prose like
     * the provenance tooltip, where printing the raw key would be worse than
     * printing nothing.
     */
    translateOrEmpty(key: string): string {
      const translated = this.$t(key) as string;
      return translated === key ? '' : translated;
    },

    formatDate(value: unknown): string {
      if (typeof value !== 'string' || !value) return NO_VALUE;
      const date = new Date(value);
      if (Number.isNaN(date.getTime())) return value;
      return date.toLocaleDateString();
    },
  },
});
</script>

